import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { Search, User } from "lucide-react";

import { Screen, ShopCard } from "../components/common/UI";

import "../styles/Home.css";

export default function Home() {
  const navigate = useNavigate();
  const [query, setQuery] = useState("");
  const [user, setUser] = useState(null);
  const [merchants, setMerchants] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // TODO: Replace with actual API call to GET /auth/me and GET /merchants
    // Mock data for now
    setUser({
      name: "Ngawang Pema",
      user_image: "https://i.pravatar.cc/100?img=47"
    });
    setMerchants([
      {
        id: "1",
        business_name: "SupaMart Grocers",
        category: "Groceries",
        image: "https://images.unsplash.com/photo-1542838132-92c53300491e?w=900",
        address: "Moi Avenue, Nairobi",
        distance_km: 1.2
      },
      {
        id: "2",
        business_name: "Fresh Market",
        category: "Groceries",
        image: "https://images.unsplash.com/photo-1604719312566-8912e9227c6a?w=900",
        address: "Parklands",
        distance_km: 2.5
      }
    ]);
    setLoading(false);
  }, []);

  const filteredMerchants = merchants.filter((merchant) =>
    `${merchant.business_name} ${merchant.address}`
      .toLowerCase()
      .includes(query.toLowerCase())
  );

  if (loading) {
    return <Screen>Loading...</Screen>;
  }

  return (
    <Screen>
      <div className="home-welcome">
        {user?.user_image ? (
          <img
            src={user.user_image}
            alt="Profile"
          />
        ) : (
          <div className="profile-placeholder">
            <User size={24} />
          </div>
        )}

        <div>
          <small>Welcome</small>
          <strong>{user?.name || "User"}</strong>
        </div>
      </div>

      <div className="search-wrap">
        <Search size={17} />

        <input
          className="search-input"
          placeholder="Search location or a Merchant"
          value={query}
          onChange={(e) => setQuery(e.target.value)}
        />
      </div>

      <h3 className="card-title">Merchants</h3>

      <div className="home-shops-list">
        {filteredMerchants.map((merchant) => (
          <ShopCard
            key={merchant.id}
            shop={{
              id: merchant.id,
              name: merchant.business_name,
              category: merchant.category,
              location: merchant.address,
              distance: merchant.distance_km ? `${merchant.distance_km} km` : null,
              image: merchant.image
            }}
            onClick={() => navigate(`/catalogue/${merchant.id}`)}
          />
        ))}
      </div>

      {filteredMerchants.length === 0 && (
        <p className="muted small">No merchants found.</p>
      )}
    </Screen>
  );
}
